`,version:`// Applique la version de app.config.json aux projets natifs g\xE9n\xE9r\xE9s par "cap add".
const fs = require("fs");
const path = require("path");
const cfg = require("../app.config.json");
function patch(file, pairs) {
  const p = path.join(__dirname, "..", file);
  if (!fs.existsSync(p)) { console.log("ignor\xE9 (plateforme non ajout\xE9e) : " + file); return; }
  let text = fs.readFileSync(p, "utf8");
  let count = 0;
  pairs.forEach(function (pair) { text = text.replace(pair[0], function () { count++; return pair[1]; }); });
  fs.writeFileSync(p, text);
  console.log(file + " : " + count + " remplacement(s)" + (count ? "" : "  (mod\xE8le natif diff\xE9rent : r\xE9glez la version \xE0 la main)"));
}
patch("android/app/build.gradle", [
  [/versionCode\\s+\\d+/, "versionCode " + cfg.versionCode],
  [/versionName\\s+"[^"]*"/, 'versionName "' + cfg.version + '"'],
]);
patch("ios/App/App.xcodeproj/project.pbxproj", [
  [/MARKETING_VERSION = [^;]*;/g, "MARKETING_VERSION = " + cfg.version + ";"],
  [/CURRENT_PROJECT_VERSION = [^;]*;/g, "CURRENT_PROJECT_VERSION = " + cfg.versionCode + ";"],
]);
