    '#im-jumelles.defaut{background:radial-gradient(circle at 33% 50%,transparent 27%,#000 28%),radial-gradient(circle at 67% 50%,transparent 27%,#000 28%);background-blend-mode:multiply}',
    '.im-marche canvas{animation:imPas .55s ease-in-out}',
    '@keyframes imPas{0%,100%{transform:translateY(0)}25%{transform:translateY(-6px) scale(1.02)}50%{transform:translateY(3px) scale(1.03)}75%{transform:translateY(-4px) scale(1.02)}}',
    '.im-casque #hud,.im-casque .hs,.im-casque .ly,.im-casque #im-boutons{display:none!important}',
    '#im-viseurs{position:absolute;inset:0;z-index:60;pointer-events:none;display:none}',
    '.im-casque #im-viseurs{display:block}',
    '.im-v{position:absolute;top:50%;width:14px;height:14px;margin:-7px;border-radius:50%;border:2px solid #fff;box-sizing:border-box}',
