function imBoutons(){
  const o = imOpt();
  const b = mk('div'); b.id = 'im-boutons';
  const ajoute = function(ic, titre, fn, id){ const x = mk('button', '', ic); x.type = 'button'; x.title = titre; x.setAttribute('aria-label', titre); if(id) x.id = id; x.addEventListener('click', function(e){ e.stopPropagation(); fn(x); }); b.appendChild(x); return x; };
  if(o.gyro) ajoute('\u{1F4F1}', 'Regarder en bougeant le t\xE9l\xE9phone', function(x){ gyroBascule(x); }, 'im-gyro');
  if(o.casque) ajoute('\u{1F97D}', 'Mode casque', function(){ casqueOuvre(); });
  if(optJeu('combat').actif) ajoute('\u{1F6E1}', 'Fiche du h\xE9ros', function(){ ficheOuvre(); });
  ajoute('\u{1F3A4}', 'Souffler dans le micro', function(x){ microBascule(x); }, 'im-micro').style.display = 'none';
  frameEl.appendChild(b);
}

/* --- gyroscope --- */
let gyroOn = false, gyroPrec = null, gyroSecoue = 0, capT = 0;
const gyE = { e: null, q: null, q0: null, q1: null, z: null, o: null };
function gyroLit(ev){
  if(!gyroOn || ev.alpha == null) return;
  if(!gyE.e){ gyE.e = new THREE.Euler(); gyE.q = new THREE.Quaternion(); gyE.q0 = new THREE.Quaternion(); gyE.q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); gyE.z = new THREE.Vector3(0, 0, 1); gyE.o = new THREE.Euler(); }
  const orient = imRad((screen.orientation && screen.orientation.angle) || window.orientation || 0);
  gyE.e.set(imRad(ev.beta), imRad(ev.alpha), -imRad(ev.gamma), 'YXZ');
  gyE.q.setFromEuler(gyE.e).multiply(gyE.q1).multiply(gyE.q0.setFromAxisAngle(gyE.z, -orient));
  gyE.o.setFromQuaternion(gyE.q, 'YXZ');
  const y = gyE.o.y, p = gyE.o.x;
  if(gyroPrec && playerScreen === 'playing' && !enMouvement()){
    const k = imOpt().sensibilite || 1;
    const dy = Math.atan2(Math.sin(y - gyroPrec.y), Math.cos(y - gyroPrec.y));
    yaw += dy * k;
    pitch = Math.max(-1.5, Math.min(1.5, pitch + (p - gyroPrec.p) * k));
    needsRedraw();
  }
  gyroPrec = { y: y, p: p };
  const t = Date.now();
  if(t - capT > 1000){
    capT = t;
    const cap = ev.webkitCompassHeading != null ? ev.webkitCompassHeading : 360 - ev.alpha;
    vars.cap_reel = Math.round(cap);
  }
}
function secoueLit(ev){
  const a = ev.accelerationIncludingGravity || ev.acceleration;
  if(!a) return;
  const n = Math.sqrt((a.x || 0) * (a.x || 0) + (a.y || 0) * (a.y || 0) + (a.z || 0) * (a.z || 0));
  const t = Date.now();
  if(n < 24 || t - gyroSecoue < 2000 || playerScreen !== 'playing') return;
  gyroSecoue = t;
  const l = imSc().secouer;
  if(l && l.length) actionsJoue(l);
}
function gyroBascule(bouton){
  const allume = function(){
    gyroOn = !gyroOn; gyroPrec = null;
    if(bouton) bouton.classList.toggle('on', gyroOn);
    window.removeEventListener('deviceorientation', gyroLit);
    window.removeEventListener('devicemotion', secoueLit);
    if(gyroOn){ window.addEventListener('deviceorientation', gyroLit); window.addEventListener('devicemotion', secoueLit); }
  };
  const D = window.DeviceOrientationEvent;
  if(!gyroOn && D && D.requestPermission) D.requestPermission().then(function(r){ if(r === 'granted') allume(); else showModal('Le t\xE9l\xE9phone a refus\xE9 l' + String.fromCharCode(39) + 'acc\xE8s au mouvement.'); }).catch(function(){ allume(); });
  else allume();
}

/* --- casque : deux vues, s\xE9lection au regard --- */
let casqueOn = false, casqueVise = null, casqueT0 = 0, casqueMarques = [];
function casqueOuvre(){
  casqueOn = true;
  frameEl.classList.add('im-casque');
  let v = document.getElementById('im-viseurs');
  if(!v){
    v = mk('div'); v.id = 'im-viseurs';
    ['25%', '75%'].forEach(function(x){ const d = mk('div', 'im-v'); d.style.left = x; v.appendChild(d); });
    const s = mk('button', '', '\u2715'); s.id = 'im-sortie'; s.type = 'button'; s.setAttribute('aria-label', 'Quitter le mode casque');
    s.addEventListener('click', function(e){ e.stopPropagation(); casqueFerme(); });
    v.appendChild(s);
    frameEl.appendChild(v);
  }
  if(!gyroOn) gyroBascule(document.getElementById('im-gyro'));
  imCasqueMarques();
  needsRedraw();
}
function casqueFerme(){
  casqueOn = false;
  frameEl.classList.remove('im-casque');
  imCasqueMarques();
  const w = mount.clientWidth, h = mount.clientHeight;
  camera.aspect = w / h; camera.updateProjectionMatrix();
  renderer.setScissorTest(false); renderer.setViewport(0, 0, w, h);
  needsRedraw();
}
function imCasqueMarques(){
  casqueMarques.forEach(function(m){ imGroupe.remove(m); });
  casqueMarques = [];
  if(!casqueOn || !current) return;
  (current.hotspots || []).forEach(function(hs){
    if(missingRequirements(hs, inventory, vars).length) return;
    const m = new THREE.Mesh(new THREE.RingGeometry(9, 12, 32), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, depthTest: false, side: THREE.DoubleSide }));
    m.position.copy(yawPitchToDir(hs.position.yaw, hs.position.pitch).multiplyScalar(300));
    m.lookAt(0, 0, 0);
    m.userData.hs = hs;
    imGroupe.add(m); casqueMarques.push(m);
  });
  (current.layers || []).forEach(function(ly){
    if(!ly.image || !ly.position) return;
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: loader.load(ly.image, function(tx){ const im = tx.image; if(im && im.width) sp.scale.y = sp.scale.x * im.height / im.width; needsRedraw(); }), transparent: true, depthTest: false }));
    const t = 70 * (ly.scale || 1);
    sp.scale.set(t, t, 1);
    sp.position.copy(yawPitchToDir(ly.position.yaw, ly.position.pitch).multiplyScalar(300));
    imGroupe.add(sp); casqueMarques.push(sp);
  });
}
function casqueTick(t){
  let vise = null, mieux = 0.13;
  (current.hotspots || []).forEach(function(hs){
    if(missingRequirements(hs, inventory, vars).length) return;
    const a = imAngle(yaw, pitch, hs.position.yaw, hs.position.pitch);
    if(a < mieux){ mieux = a; vise = hs; }
  });
  document.querySelectorAll('.im-v').forEach(function(d){ d.classList.toggle('vise', !!vise); });
  if(vise !== casqueVise){ casqueVise = vise; casqueT0 = t; }
  if(vise && t - casqueT0 > 1400){ casqueT0 = t + 3000; try{ activate(vise); }catch(e){} }
}
function imRendu(){
  if(!casqueOn){ renderer.render(scene, camera); return; }
  const w = mount.clientWidth, h = mount.clientHeight, m = Math.floor(w / 2);
  camera.aspect = m / h; camera.updateProjectionMatrix();
  renderer.setScissorTest(true);
  renderer.setViewport(0, 0, m, h); renderer.setScissor(0, 0, m, h); renderer.render(scene, camera);
  renderer.setViewport(m, 0, m, h); renderer.setScissor(m, 0, m, h); renderer.render(scene, camera);
}

/* --- jumelles, toucher un objet 3D --- */
let imJum = false, imFov0 = 0, imAppui = 0, imDown = null;
function imGestes(){
  mount.addEventListener('pointerdown', function(e){
    imDown = { x: e.clientX, y: e.clientY, t: Date.now() };
    const j = imOpt().jumelles;
    if(j && j.actif && playerScreen === 'playing'){ clearTimeout(imAppui); imAppui = setTimeout(function(){ imJumelles(true); }, 450); }
  }, { passive: true });
  mount.addEventListener('pointermove', function(e){
    if(imDown && !imJum && Math.abs(e.clientX - imDown.x) + Math.abs(e.clientY - imDown.y) > 10) clearTimeout(imAppui);
  }, { passive: true });
  const fin = function(e){
    clearTimeout(imAppui);
    if(imJum) imJumelles(false);
    const d = imDown; imDown = null;
    if(d && e.type === 'pointerup' && Math.abs(e.clientX - d.x) + Math.abs(e.clientY - d.y) < 8 && Date.now() - d.t < 400){ imToucheObjet(e); if(!ptlToucher(e)) solToucher(e); } else solCacher();
  };
  window.addEventListener('pointerup', fin); window.addEventListener('pointercancel', fin);
}
function imJumelles(on){
  const j = imOpt().jumelles || {}, el = document.getElementById('im-jumelles');
  imJum = on;
  if(on){
    imFov0 = camera.fov;
    camera.fov = Math.max(12, imFov0 / (j.zoom || 3)); camera.updateProjectionMatrix();
    el.style.display = 'block';
    if(j.image){ el.className = ''; el.style.backgroundImage = 'url("' + j.image + '")'; } else el.className = 'defaut';
  } else {
    camera.fov = imFov0; camera.updateProjectionMatrix();
    el.style.display = 'none';
  }
  needsRedraw();
}
function imToucheObjet(e){
  if(!imObjets.length || playerScreen !== 'playing') return;
  const r = mount.getBoundingClientRect();
  const v = new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
  const ray = new THREE.Raycaster(); ray.setFromCamera(v, camera);
  for(let i = 0; i < imObjets.length; i++){
    const o = imObjets[i];
    if(o.def.actions && o.def.actions.length && ray.intersectObject(o.groupe, true).length){ actionsJoue(o.def.actions); return; }
  }
}

/* --- ce que porte la sc\xE8ne --- */
function imVide(){
  imLumieres = []; imObjets = [];
  imVideos.forEach(function(v){ try{ v.pause(); v.removeAttribute('src'); v.load(); }catch(e){} });
  imVideos = [];
  while(imGroupe.children.length){
    const c = imGroupe.children[0];
    imGroupe.remove(c);
    c.traverse(function(o){
      if(o.geometry) o.geometry.dispose();
      if(o.material){ if(o.material.map) o.material.map.dispose(); o.material.dispose(); }
    });
  }
  casqueMarques = [];
}
function imHalo(couleur){
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d'), d = g.createRadialGradient(64, 64, 2, 64, 64, 64);
  d.addColorStop(0, couleur); d.addColorStop(0.3, couleur + 'AA'); d.addColorStop(1, couleur + '00');
  g.fillStyle = d; g.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}
function imLumiere(l){
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: imHalo(l.couleur || '#FFD27A'), blending: THREE.AdditiveBlending, depthTest: false, transparent: true }));
  s.position.copy(yawPitchToDir(l.yaw || 0, l.pitch || 0).multiplyScalar(400));
  const t = 2 * 400 * Math.tan(imRad(l.taille || 12) / 2);
  s.scale.set(t, t, 1);
  imGroupe.add(s);
  imLumieres.push({ s: s, mode: l.mode || 'vacille', graine: Math.random() * 10 });
}
function imEcran(e){
  if(!e.src) return;
  const v = document.createElement('video');
  v.src = e.src; v.loop = e.boucle !== false; v.muted = !e.son; v.playsInline = true; v.setAttribute('playsinline', ''); v.crossOrigin = 'anonymous';
  const p = v.play(); if(p && p.catch) p.catch(function(){});
  const d = 300, w = 2 * d * Math.tan(imRad(e.largeur || 30) / 2), h = 2 * d * Math.tan(imRad(e.hauteur || 18) / 2);
  const tex = new THREE.VideoTexture(v); tex.minFilter = THREE.LinearFilter;
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide }));
  m.position.copy(yawPitchToDir(e.yaw || 0, e.pitch || 0).multiplyScalar(d));
  m.lookAt(0, 0, 0);
  imGroupe.add(m); imVideos.push(v);
}
/*  Un lecteur GLB r\xE9duit : g\xE9om\xE9trie, couleur et texture de base.     */
function glbLit(buf){
  const dv = new DataView(buf);
  if(dv.getUint32(0, true) !== 0x46546C67) throw new Error('GLB');
  let o = 12, json = null, bin = null;
  while(o < buf.byteLength){
    const n = dv.getUint32(o, true), t = dv.getUint32(o + 4, true);
    if(t === 0x4E4F534A) json = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, o + 8, n)));
    else if(t === 0x004E4942) bin = buf.slice(o + 8, o + 8 + n);
    o += 8 + n;
  }
  const lit = function(i){
    const a = json.accessors[i], bv = json.bufferViews[a.bufferView], off = (bv.byteOffset || 0) + (a.byteOffset || 0);
    const n = { SCALAR: 1, VEC2: 2, VEC3: 3, VEC4: 4 }[a.type];
    const T = { 5120: Int8Array, 5121: Uint8Array, 5122: Int16Array, 5123: Uint16Array, 5125: Uint32Array, 5126: Float32Array }[a.componentType];
    const out = new T(a.count * n), src = new Uint8Array(bin), taille = T.BYTES_PER_ELEMENT, pas = bv.byteStride || n * taille;
    const tmp = new Uint8Array(out.buffer);
    for(let k = 0; k < a.count; k++) tmp.set(src.subarray(off + k * pas, off + k * pas + n * taille), k * n * taille);
    return { d: out, n: n };
  };
  const matiere = function(i){
    const m = i == null ? {} : json.materials[i], pb = m.pbrMetallicRoughness || {}, c = pb.baseColorFactor || [1, 1, 1, 1];
    const r = new THREE.MeshLambertMaterial({ color: new THREE.Color(c[0], c[1], c[2]), transparent: c[3] < 1, opacity: c[3], side: THREE.DoubleSide });
    if(pb.baseColorTexture && json.textures){
      const im = json.images[json.textures[pb.baseColorTexture.index].source];
      if(im.bufferView != null){
        const bv = json.bufferViews[im.bufferView];
        const u = URL.createObjectURL(new Blob([new Uint8Array(bin, bv.byteOffset || 0, bv.byteLength)], { type: im.mimeType || 'image/png' }));
        r.map = loader.load(u, function(){ needsRedraw(); }); r.map.flipY = false;
      }
    }
    return r;
  };
  const noeud = function(i){
    const n = json.nodes[i], g = new THREE.Group();
    if(n.matrix) g.applyMatrix4(new THREE.Matrix4().fromArray(n.matrix));
    else {
      if(n.translation) g.position.fromArray(n.translation);
      if(n.rotation) g.quaternion.fromArray(n.rotation);
      if(n.scale) g.scale.fromArray(n.scale);
    }
    if(n.mesh != null) json.meshes[n.mesh].primitives.forEach(function(pr){
      const geo = new THREE.BufferGeometry(), at = pr.attributes;
      const p = lit(at.POSITION); geo.setAttribute('position', new THREE.BufferAttribute(p.d, 3));
      if(at.NORMAL != null) geo.setAttribute('normal', new THREE.BufferAttribute(lit(at.NORMAL).d, 3));
      if(at.TEXCOORD_0 != null) geo.setAttribute('uv', new THREE.BufferAttribute(lit(at.TEXCOORD_0).d, 2));
      if(pr.indices != null) geo.setIndex(new THREE.BufferAttribute(lit(pr.indices).d, 1));
      if(at.NORMAL == null) geo.computeVertexNormals();
      g.add(new THREE.Mesh(geo, matiere(pr.material)));
    });
    (n.children || []).forEach(function(c){ g.add(noeud(c)); });
    return g;
  };
  const racine = new THREE.Group();
  json.scenes[json.scene || 0].nodes.forEach(function(i){ racine.add(noeud(i)); });
  return racine;
}
function imObjet(def, pour){
  if(!def.src) return;
  fetch(def.src).then(function(r){ return r.arrayBuffer(); }).then(function(b){
    if(pour !== current) return;
    const modele = glbLit(b);
    const boite = new THREE.Box3().setFromObject(modele), taille = boite.getSize(new THREE.Vector3()), centre = boite.getCenter(new THREE.Vector3());
    modele.position.sub(centre);
    const d = def.distance || 200, voulu = 2 * d * Math.tan(imRad(def.taille || 20) / 2), k = voulu / Math.max(taille.x, taille.y, taille.z, 0.0001);
    const g = new THREE.Group(); g.add(modele); g.scale.setScalar(k);
    g.position.copy(yawPitchToDir(def.yaw || 0, def.pitch || 0).multiplyScalar(d));
    g.rotation.y = imRad(def.rotation || 0);
    imGroupe.add(g);
    if(def.ombre !== false){
      const o = new THREE.Mesh(new THREE.CircleGeometry(voulu * 0.45, 32), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.35, depthWrite: false }));
      o.rotation.x = -Math.PI / 2; o.position.copy(g.position); o.position.y -= voulu * 0.5; imGroupe.add(o);
    }
    imObjets.push({ groupe: g, def: def });
    needsRedraw();
  }).catch(function(e){ if(EN_TEST) console.error('Mod\xE8le 3D illisible', e); });
}
function imZones(){
  const z = (imSc().zones || []).slice(0, 6);
  imZonesOn = z.length > 0;
  for(let i = 0; i < 6; i++){
    const q = imU.q.value[i], c = imU.z.value[i], d = z[i];
    if(!d){ q.set(0, 0, 0, 0); continue; }
    let u = -(d.yaw || 0) / (2 * Math.PI) - 0.25; u = u - Math.floor(u);
    c.set(u, 0.5 + (d.pitch || 0) / Math.PI, Math.max(0.005, (d.largeur || 40) / 720), Math.max(0.005, (d.hauteur || 25) / 360));
    q.set(d.effet === 'feu' ? 3 : d.effet === 'vent' ? 2 : 1, d.force == null ? 1 : d.force, 0, 0);
  }
}
function imScenePose(change){
  imInit();
  imVide();
  const s = imSc();
  (s.lumieres || []).forEach(imLumiere);
  (s.ecrans || []).forEach(imEcran);
  (s.objets || []).forEach(function(o){ imObjet(o, current); });
  imZones();
  imCasqueMarques();
  const mic = document.getElementById('im-micro');
  if(mic) mic.style.display = s.souffle && s.souffle.length ? '' : 'none';
  if(change && s.portes && s.portes.actif) imPortes(s.portes);
  if(change && imOpt().marche && !puzReduceMotion()){
    mount.classList.remove('im-marche'); void mount.offsetWidth; mount.classList.add('im-marche');
    setTimeout(function(){ mount.classList.remove('im-marche'); }, 600);
  }
}

function imPortes(p){
  const g = mk('div', 'im-porte'), d = mk('div', 'im-porte');
  g.style.left = '0'; d.style.right = '0';
  if(p.image){ const u = 'url("' + p.image + '")'; g.style.backgroundImage = u; d.style.backgroundImage = u; g.style.backgroundPosition = 'left center'; d.style.backgroundPosition = 'right center'; }
  else { g.style.borderRight = '2px solid #000'; d.style.borderLeft = '2px solid #000'; }
  frameEl.appendChild(g); frameEl.appendChild(d);
  setTimeout(function(){ g.style.transform = 'translateX(-101%)'; d.style.transform = 'translateX(101%)'; }, 260);
  setTimeout(function(){ g.remove(); d.remove(); }, 1350);
}

/* --- ce qui r\xE9agit au regard --- */
function imRegards(t){
  if(cmbV) return;
  const s = imSc(), l = s.regards || [];
  l.forEach(function(r, i){
    if(r.conditions && r.conditions.length && !moOk(r.conditions)) return;
    const cle = '__regard:' + current.id + ':' + i;
    if(r.uneFois !== false && vars[cle]) return;
    const a = imAngle(yaw, pitch, r.yaw || 0, r.pitch || 0), ray = imRad(r.rayon || 15);
    const dedans = r.mode === 'dos' ? a > Math.PI - ray : a < ray;
    if(r.mode === 'vibre'){
      if(dedans && navigator.vibrate){ try{ navigator.vibrate(Math.round(10 + 40 * (1 - a / ray))); }catch(e){} }
      return;
    }
    if(!dedans){ r._t = 0; return; }
    if(r.mode === 'fixe'){
      if(!r._t) r._t = t;
      if(t - r._t < (r.duree || 2) * 1000) return;
    }
    r._t = 0;
    vars[cle] = true;
    if(r.actions && r.actions.length) actionsJoue(r.actions);
  });
  (current.layers || []).forEach(function(ly, i){
    const el = layerEls[i];
    if(!el || !(ly.regardImage || ly.gaucheImage || ly.droiteImage)) return;
    const dy = Math.atan2(Math.sin(ly.position.yaw - yaw), Math.cos(ly.position.yaw - yaw));
    const a = imAngle(yaw, pitch, ly.position.yaw, ly.position.pitch);
    let src = ly.image;
    if(a < 0.2 && ly.regardImage) src = ly.regardImage;
    else if(dy > 0.2 && ly.gaucheImage) src = ly.gaucheImage;
    else if(dy < -0.2 && ly.droiteImage) src = ly.droiteImage;
    if(el._im !== src){ el._im = src; el.src = src; }
  });
}
function imTick(){
  if(!imPret) imInit();
  const t = performance.now(), o = imOpt(), s = imSc(), joue = playerScreen === 'playing' && !!current;
  imU.t.value = t / 1000;
  imOff.y = 0; imOff.p = 0;
  if(joue){
    const bouge = enMouvement();
    if(bouge){ imVy = Math.max(-0.08, Math.min(0.08, yaw - imPy)); imVp = Math.max(-0.05, Math.min(0.05, pitch - imPp)); }
    else if(o.inertie && !gyroOn && (Math.abs(imVy) > 0.0004 || Math.abs(imVp) > 0.0004)){
      yaw += imVy; pitch = Math.max(-1.5, Math.min(1.5, pitch + imVp));
      imVy *= 0.93; imVp *= 0.93; needsRedraw();
    }
    imPy = yaw; imPp = pitch;
    if(o.respiration && !bouge && !puzReduceMotion()){ imOff.y = Math.sin(t / 2600) * 0.006; imOff.p = Math.sin(t / 1900) * 0.004; }
    const li = s.limites;
    if(li){
      if(li.pitchMin != null) pitch = Math.max(imRad(li.pitchMin), pitch);
      if(li.pitchMax != null) pitch = Math.min(imRad(li.pitchMax), pitch);
      if(li.largeur > 0 && li.largeur < 360){
        const c = imRad(li.centre), m = imRad(li.largeur) / 2, d = Math.atan2(Math.sin(yaw - c), Math.cos(yaw - c));
        if(Math.abs(d) > m) yaw = c + (d > 0 ? m : -m);
      }
    }
    if(o.confort){
      const v = Math.min(1, Math.abs(yaw - imDerniere) * 18), el = document.getElementById('im-vignette');
      if(el){ const w = parseFloat(el.style.opacity) || 0, n = w + (v - w) * 0.2; if(Math.abs(n - w) > 0.005 || n > 0.01) el.style.opacity = n < 0.01 ? '0' : String(n); }
    }
    imDerniere = yaw;
  }
  imLumieres.forEach(function(l){
    const m = l.s.material;
    if(l.mode === 'vacille') m.opacity = 0.72 + 0.22 * Math.sin(t / 90 + l.graine) * Math.sin(t / 233 + l.graine);
    else if(l.mode === 'clignote') m.opacity = Math.sin(t / 420 + l.graine) > 0 ? 1 : 0.12;
    else m.opacity = 0.9;
  });
  imObjets.forEach(function(x){ if(x.def.tourne) x.groupe.rotation.y += 0.008; });
  if(casqueOn && joue) casqueTick(t);
  if(joue && t - imDernierLeger > 200){ imDernierLeger = t; try{ imRegards(t); }catch(e){} }
}
function imAnime(){
  return imZonesOn || imVideos.length > 0 || casqueOn || imLumieres.some(function(l){ return l.mode !== 'fixe'; }) || imObjets.some(function(x){ return x.def.tourne; })
    || Math.abs(imVy) > 0.0004 || Math.abs(imVp) > 0.0004 || !!imOpt().respiration;
}

/* --- souffler dans le micro --- */
let micro = null;
function microBascule(bouton){
  if(micro){ micro.fin(); micro = null; bouton.classList.remove('on'); return; }
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;
  navigator.mediaDevices.getUserMedia({ audio: true }).then(function(flux){
    const C = window.AudioContext || window.webkitAudioContext, ac = new C(), an = ac.createAnalyser();
    ac.createMediaStreamSource(flux).connect(an);
    const d = new Uint8Array(an.fftSize);
    let fort = 0;
    const iv = setInterval(function(){
      an.getByteTimeDomainData(d);
      let m = 0;
      for(let i = 0; i < d.length; i += 8) m = Math.max(m, Math.abs(d[i] - 128));
      fort = m > 70 ? fort + 1 : 0;
      if(fort >= 4 && playerScreen === 'playing'){
        fort = -20;
        const l = imSc().souffle;
        if(l && l.length) actionsJoue(l);
      }
    }, 100);
    micro = { fin: function(){ clearInterval(iv); flux.getTracks().forEach(function(k){ k.stop(); }); ac.close(); } };
    bouton.classList.add('on');
  }).catch(function(){ showModal('Le micro n' + String.fromCharCode(39) + 'est pas disponible.'); });
}
/* --- sursaut --- */
function imSursaut(a){
  if(puzReduceMotion()) return;
  const el = mk('div', 'im-sursaut');
  if(a.image) el.style.backgroundImage = 'url("' + a.image + '")';
  frameEl.appendChild(el);
  try{ vibre(200); }catch(e){}
  setTimeout(function(){ el.remove(); }, Math.max(150, (a.duree || 0.7) * 1000));
}

/* ---- Lot 19 : le h\xE9ros et les combats ----------------------------- */
function cmbCfg(){ return optJeu('combat'); }
const CMB_PLACES = [['arme', 'Arme'], ['armure', 'Armure'], ['bijou', 'Bijou']];
function cmbItem(id){ return id ? hudItemDef(id, GAME.inventory_items || []) : null; }
function cmbNb(id){ return uiNumberOf(inventory[id]); }
function heroEtat(){
  if(!vars.__heros || typeof vars.__heros !== 'object') vars.__heros = { niveau: 1, xp: 0, vie: null, energie: null, equip: {} };
  return vars.__heros;
}
function heroStats(){
  const c = cmbCfg().heros || {}, h = heroEtat(), n = h.niveau - 1;
  const s = {
    vieMax: c.vie + c.gainVie * n, energieMax: c.energie + c.gainEnergie * n,
    attaque: c.attaque + c.gainAttaque * n, defense: c.defense + c.gainDefense * n,
    vitesse: c.vitesse, chance: c.chance
  };
  CMB_PLACES.forEach(function(p){
    const id = h.equip[p[0]], it = cmbItem(id);
    if(id && cmbNb(id) < 1){ delete h.equip[p[0]]; return; }
    if(it && it.equip) ['attaque', 'defense', 'vitesse', 'chance'].forEach(function(k){ s[k] += it.equip[k] || 0; });
    if(it && it.equip) s.vieMax += it.equip.vie || 0;
  });
  if(h.vie == null || h.vie > s.vieMax) h.vie = s.vieMax;
  if(h.energie == null || h.energie > s.energieMax) h.energie = s.energieMax;
  return s;
}
/*  Les variables heros_\u2026 servent aux conditions et aux jets de d\xE9s.    */
function heroSync(){
  if(!cmbCfg().actif) return;
  const s = heroStats(), h = heroEtat();
  vars.heros_vie = h.vie; vars.heros_vie_max = s.vieMax; vars.heros_energie = h.energie;
  vars.heros_niveau = h.niveau; vars.heros_xp = h.xp;
  vars.heros_attaque = s.attaque; vars.heros_defense = s.defense; vars.heros_vitesse = s.vitesse; vars.heros_chance = s.chance;
}
function xpPour(n){ return Math.round((cmbCfg().heros.xpBase || 20) * Math.pow(n, 1.5)); }
function heroGagneXp(n){
  const c = cmbCfg().heros, h = heroEtat(), monte = [];
  h.xp += n;
  while(h.niveau < (c.niveauMax || 20) && h.xp >= xpPour(h.niveau)){
    h.xp -= xpPour(h.niveau); h.niveau += 1; monte.push(h.niveau);
  }
  if(monte.length){
    h.vie = null; h.energie = null; heroSync();
    try{ hudPlaySound('notify'); }catch(e){}
    annonce('Niveau sup\xE9rieur', 'Niveau ' + h.niveau, '', '\u2B50');
    if(c.surNiveau && c.surNiveau.length) actionsJoue(c.surNiveau);
  } else heroSync();
  return monte;
}
function heroSoigne(pv, pe){
  const s = heroStats(), h = heroEtat();
  h.vie = Math.min(s.vieMax, h.vie + Math.round(s.vieMax * (pv || 0) / 100));
  h.energie = Math.min(s.energieMax, h.energie + Math.round(s.energieMax * (pe || 0) / 100));
  heroSync();
}
