    const cv = document.createElement('canvas'); cv.width = 320; cv.height = 200;
    cv.style.cssText = 'width:100%;display:block;background:#000;border-radius:4px'; g.appendChild(cv);
    const o = { sc: sc, cv: cv, im: null };
