const PZ_BOUTONS_DEFAUT = { retour: { x: 0.08, y: 0.06, visible: true }, annuler: { x: 0.62, y: 0.06, visible: true }, indice: { x: 0.76, y: 0.06, visible: true }, recommencer: { x: 0.9, y: 0.06, visible: true } };
