function uiNum(v, d, min, max) {
const n = Number(v);
if (!isFinite(n)) return d;
return Math.max(min, Math.min(max, n));
}
function uiStr(v, d) {
if (typeof v === "string") return v;
return d === undefined ? "" : d;
}
function uiOneOf(v, list, d) { return list.indexOf(v) >= 0 ? v : d; }
function uiColor(v, d) {
if (typeof v !== "string") return d;
if (/^#[0-9a-fA-F]{3,8}$/.test(v)) return v;
const open = v.indexOf("(");
if (open > 2 && open < 6 && /^(rgb|rgba|hsl|hsla)$/.test(v.slice(0, open))) return v;
return d;
}
