      d.style.backgroundSize = (p.cols * 100) + '% ' + (p.rows * 100) + '%';
      d.style.backgroundPosition = (p.cols > 1 ? (k % p.cols) / (p.cols - 1) * 100 : 0) + '% ' + (p.rows > 1 ? Math.floor(k / p.cols) / (p.rows - 1) * 100 : 0) + '%';
