id: id,
label: ddStr(s.label, 40),
image: typeof s.image === 'string' ? s.image : '',
x: Math.round(puzNum(s.x, 20, -2000, 4000)),
y: Math.round(puzNum(s.y, 20, -2000, 4000)),
