var pris = {};
for (i = 0; i < p.pieces.length; i++) if (placed[p.pieces[i].id]) pris[placed[p.pieces[i].id]] = 1;
for (i = 0; i < p.targets.length; i++) if (!pris[p.targets[i].id]) return false;
