host.textContent = '';
host.appendChild(wrap);
var consigne = motEl('div', 'pz-sc-consigne', p.consigne);
var barre = motEl('div', 'pz-sc-tenue');
var plein = motEl('div', 'pz-sc-tenue-plein');
barre.setAttribute('data-sc-tenue', '1');
barre.appendChild(plein);
var indice = motEl('div', 'pz-sc-indice');
indice.setAttribute('data-sc-indice', '1');
wrap.appendChild(consigne);
wrap.appendChild(barre);
if (p.regard.indice) wrap.appendChild(indice);
