        const fb = hmk("img", { position: "absolute", left: "0", top: "0", width: "100%", height: "100%", objectFit: L.fit || "cover", display: L.fallback ? "block" : "none", pointerEvents: "none" });
        fb.setAttribute("alt", ""); if (L.fallback) fb.src = L.fallback;
